#!/usr/bin/env bash
# Generates random secrets for the docker-compose dev stack into .env (git-ignored).
# Run once; re-running keeps existing values unless you pass --force.
#   scripts/dev-secrets.sh && docker compose -f docker-compose.dev.yml up --build
set -euo pipefail
cd "$(dirname "$0")/.."

if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists (use --force to regenerate). Test logins:"
  grep -E '^(MEMBER|LIBRARIAN)_PASSWORD=' .env
  exit 0
fi

rand() { head -c 32 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c "${1:-24}"; }

cat > .env <<ENV
# Generated by scripts/dev-secrets.sh. Local development only; never commit.
KEYCLOAK_ADMIN_PASSWORD=$(rand)
BFF_CLIENT_SECRET=$(rand 40)
SERVICES_CLIENT_SECRET=$(rand 40)
VALKEY_PASSWORD=$(rand)
MEMBER_PASSWORD=$(rand 16)
LIBRARIAN_PASSWORD=$(rand 16)
ENV
chmod 600 .env
echo "Wrote .env. Sign in at http://localhost:3000 as:"
echo "  member1     / $(grep ^MEMBER_PASSWORD= .env | cut -d= -f2)"
echo "  librarian1  / $(grep ^LIBRARIAN_PASSWORD= .env | cut -d= -f2)   (asks you to set up an authenticator app)"
echo "Keycloak admin console: http://localhost:3000/auth/admin  (admin / see .env)"
